// Generar bloques de horario disponibles para la fecha solicitada
const fecha = $('Tool Trigger: Consultar Disponibilidad').first().json.fecha || new Date().toISOString().split('T')[0];
const duracion = $input.first().json.duracion_minutos || 60;
const nombreServicio = $input.first().json.nombre || 'Servicio';

// Simulación inteligente de slots (en producción se cruza con Google Calendar API)
const slotsDisponibles = [
  `${fecha} 09:30:00`,
  `${fecha} 11:45:00`,
  `${fecha} 15:00:00`,
  `${fecha} 17:30:00`
];

return [{
  json: {
    servicio: nombreServicio,
    duracion_minutos: duracion,
    fecha_consultada: fecha,
    horarios_disponibles: slotsDisponibles,
    mensaje_sugerido: `Tenemos disponibilidad para ${nombreServicio} el ${fecha} a las: 9:30 AM, 11:45 AM, 3:00 PM y 5:30 PM.`
  }
}];
